apply.studio_css:
/* Typography Studio · personality=innovation · pair=oswald_source */
:root {
  --font-display: "Oswald", "Arial Narrow", sans-serif;
  --font-body: "Source Sans 3", "Segoe UI", system-ui, sans-serif;
  --font-sans: "Source Sans 3", "Segoe UI", system-ui, sans-serif;
  --type-body-lh: 1.55;
  --type-headline-lh: 1.15;
  --type-track-display: -0.01em;
  --type-track-body: 0;
  --type-btn-weight: 700;
}
body {
  font-family: var(--font-body);
  font-weight: 400;
  line-height: var(--type-body-lh);
  letter-spacing: var(--type-track-body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body .hero h1,
body .hero .hero-title,
body h1,
body .page-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(1.9rem, 4.2vw, 2.85rem);
  line-height: var(--type-headline-lh);
  letter-spacing: var(--type-track-display);
}
body .section h2,
body h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(1.35rem, 2.2vw, 1.75rem);
  line-height: 1.2;
  letter-spacing: var(--type-track-display);
}
body .btn,
body button.btn,
body a.btn {
  font-family: var(--font-body);
  font-weight: var(--type-btn-weight);
  letter-spacing: 0.02em;
}
@media (max-width: 720px) {
  body { line-height: 1.45; }
  body .hero h1,
  body .hero .hero-title,
  body h1 {
    font-size: clamp(1.7rem, 7vw, 2.2rem);
    letter-spacing: -0.015em;
  }
}

